guided.solution:
CREATE TABLE inventory (item text PRIMARY KEY, qty int);
INSERT INTO inventory VALUES ('apple', 10), ('banana', 4);
INSERT INTO inventory VALUES ('apple', 20), ('cherry', 5)
ON CONFLICT (item) DO UPDATE SET qty = EXCLUDED.qty;
SELECT item, qty FROM inventory ORDER BY item;
